<?php
declare(strict_types=1);
namespace ReadyFinance;
final class Http {
 public static function run():void {
  ini_set('display_errors','0');ini_set('log_errors','1');
  header('X-Content-Type-Options: nosniff');header('Referrer-Policy: same-origin');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'");header('Cache-Control: no-store');
  try{$c=new Core();$dir=$c->config['storage'].'/sessions';if(!is_dir($dir))mkdir($dir,0700,true);session_save_path($dir);session_name('readyfinance');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Strict','path'=>$c->config['base_path']?:'/']);session_start();if(($_SESSION['installation_uuid']??null)!==$c->config['installation_uuid']||(isset($_SESSION['last'])&&time()-$_SESSION['last']>1800)||(isset($_SESSION['started'])&&time()-$_SESSION['started']>28800)){$_SESSION=[];session_regenerate_id(true);}$_SESSION['installation_uuid']=$c->config['installation_uuid'];$_SESSION['started']??=time();$_SESSION['last']=time();$_SESSION['csrf']??=bin2hex(random_bytes(32));
   $route=$_GET['api']??null;if($route===null&&preg_match('#/api/v1/([a-z_/-]+)$#',parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),$match))$route=$match[1];if($route===null){header('Content-Type: text/html; charset=utf-8');readfile(dirname(__DIR__,2).'/resources/shell.html');return;}
   header('Content-Type: application/json; charset=utf-8');$method=$_SERVER['REQUEST_METHOD'];$p=[];if($method==='POST'){if(!hash_equals($_SESSION['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))throw new Fault('Session expired. Refresh and try again.',403);if((int)($_SERVER['CONTENT_LENGTH']??0)>11000000)throw new Fault('File or request is too large.');if(str_contains($_SERVER['CONTENT_TYPE']??'','application/json')){$raw=file_get_contents('php://input');if(strlen($raw)>150000)throw new Fault('Request is too large.');$p=json_decode($raw,true,64,JSON_THROW_ON_ERROR);if(!is_array($p))throw new Fault('Invalid request.');}else{$p=$_POST;}}
   $f=new Finance($c);
   if($route==='session'){self::json(['csrf'=>$_SESSION['csrf'],'setup'=>$c->query('SELECT COUNT(*) FROM users')->fetchColumn()==0,'authenticated'=>isset($_SESSION['uid'])]);return;}
   if($route==='setup'&&$method==='POST'){if(!in_array($_SERVER['REMOTE_ADDR']??'',['127.0.0.1','::1'],true))throw new Fault('Complete first setup on the WAMP computer.',403);$r=$f->setup($p);session_regenerate_id(true);$_SESSION['uid']=$r['user_id'];$_SESSION['hid']=$r['household_id'];self::json(['ok'=>true]);return;}
   if($route==='login'&&$method==='POST'){$email=strtolower(trim((string)($p['email']??'')));$key=hash('sha256',($_SERVER['REMOTE_ADDR']??'').'|'.$email);$a=$c->one('SELECT attempts,UNIX_TIMESTAMP(last_at) stamp FROM login_attempts WHERE key_hash=?',[$key]);if($a&&$a['attempts']>=8&&time()-$a['stamp']<900)throw new Fault('Too many attempts. Try again in 15 minutes.',429);$u=$c->one('SELECT u.*,m.household_id,m.role FROM users u JOIN household_memberships m ON m.user_id=u.id AND m.active=1 WHERE u.email=? LIMIT 1',[$email]);if(!$u||!password_verify((string)($p['password']??''),$u['password_hash'])){$c->query('INSERT INTO login_attempts VALUES(?,1,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE attempts=IF(last_at<UTC_TIMESTAMP()-INTERVAL 15 MINUTE,1,attempts+1),last_at=UTC_TIMESTAMP(6)',[$key]);throw new Fault('Email or password is incorrect.',401);}$c->query('DELETE FROM login_attempts WHERE key_hash=?',[$key]);session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['hid']=$u['household_id'];self::json(['ok'=>true]);return;}
   if(!isset($_SESSION['uid'],$_SESSION['hid']))throw new Fault('Please sign in.',401);$h=(int)$_SESSION['hid'];$uid=(int)$_SESSION['uid'];$user=$c->one('SELECT u.*,m.role FROM users u JOIN household_memberships m ON m.user_id=u.id WHERE u.id=? AND m.household_id=? AND m.active=1',[$uid,$h]);if(!$user)throw new Fault('Access was revoked.',403);
   if($route==='logout'&&$method==='POST'){$_SESSION=[];session_regenerate_id(true);self::json(['ok'=>true]);return;}
   if($route==='snapshot'&&$method==='GET'){self::json($f->snapshot($h,$user));return;}
   if($route==='document'&&$method==='GET'){$d=$c->scope('documents',$_GET['uuid']??'',$h);$file=$c->config['storage'].'/documents/'.$d['storage_key'];if(!is_file($file))throw new Fault('The file is unavailable.',404);header('Content-Type: '.$d['mime']);header('Content-Disposition: attachment; filename="'.rawurlencode($d['filename']).'"');readfile($file);return;}
   if($method!=='POST')throw new Fault('Unknown route.',404);if(!in_array($user['role'],['owner','manager'],true))throw new Fault('Your role does not allow this action.',403);
   $key=$_SERVER['HTTP_IDEMPOTENCY_KEY']??'';
   switch($route){
    case 'transaction':$r=(new Accounting($c))->post($h,$uid,$p,$key);break;
    case 'reverse':$r=(new Accounting($c))->reverse($h,$uid,$p['uuid']??'',Core::date($p['date']??''),Core::text($p['reason']??'',400),$key);break;
    case 'create':$r=$f->create($h,$uid,$p['kind']??'',$p,$key);break;
    case 'reserve':if(strlen($key)<8)throw new Fault('Command key required.');$r=$f->reserve($h,$uid,$p,$key);break;
    case 'recurring':$r=$f->runRecurring($h,$uid);break;
    case 'period':if($user['role']!=='owner')throw new Fault('Only the owner can lock periods.',403);$month=substr(Core::date(($p['month']??'').'-01'),0,7);$reason=Core::text($p['reason']??'',250);$r=$c->atomic(function()use($c,$h,$uid,$month,$reason,$p){$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$c->query('INSERT INTO periods(household_id,month,locked,reason) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE locked=VALUES(locked),reason=VALUES(reason)',[$h,$month,!empty($p['locked'])?1:0,$reason]);$c->audit($h,$uid,'period.changed',null,['month'=>$month,'locked'=>!empty($p['locked']),'reason'=>$reason]);return ['ok'=>true];});break;
    case 'upload':$r=self::upload($c,$h,$uid);break;
    case 'backup':if($user['role']!=='owner')throw new Fault('Only the owner can create backups.',403);self::backup($c,$h,$uid,$p);return;
    default:throw new Fault('Unknown route.',404);
   }self::json($r);
  }catch(Fault $e){http_response_code($e->status);self::json(['error'=>$e->getMessage()]);}catch(\JsonException $e){http_response_code(400);self::json(['error'=>'Invalid JSON request.']);}catch(\Throwable $e){$id=bin2hex(random_bytes(6));error_log('ReadyFinance '.$id.' '.get_class($e).' '.$e->getMessage());http_response_code(500);self::json(['error'=>'The action could not be completed. Reference '.$id]);}
 }
 private static function json(array $data):void{echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);}
 private static function upload(Core $c,int $h,int $u):array{
  $f=$_FILES['file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>10000000)throw new Fault('Choose a PDF JPG or PNG smaller than 10 MB.');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['application/pdf','image/jpeg','image/png'],true))throw new Fault('Only PDF JPG and PNG are accepted.');$t=!empty($_POST['transaction_uuid'])?$c->scope('transactions',$_POST['transaction_uuid'],$h):null;$key=bin2hex(random_bytes(32));$dir=$c->config['storage'].'/documents';if(!is_dir($dir))mkdir($dir,0700,true);$path=$dir.'/'.$key;if(!move_uploaded_file($f['tmp_name'],$path))throw new Fault('Could not save the file.',500);try{return $c->atomic(function()use($c,$h,$u,$f,$mime,$key,$path,$t){$uuid=Core::uuid();$c->insert('documents',['uuid'=>$uuid,'household_id'=>$h,'transaction_id'=>$t['id']??null,'filename'=>Core::text(basename($f['name']),190),'storage_key'=>$key,'mime'=>$mime,'bytes'=>$f['size'],'checksum'=>hash_file('sha256',$path),'created_at'=>Core::now()]);$c->audit($h,$u,'document.uploaded',$uuid);return ['uuid'=>$uuid];});}catch(\Throwable $e){unlink($path);throw $e;}
 }
 private static function backup(Core $c,int $h,int $u,array $p):void{
  $password=(string)($p['password']??'');if(strlen($password)<12||strlen($password)>200)throw new Fault('Use a backup password of 12 to 200 characters.');if($c->query('SELECT COUNT(*) FROM households')->fetchColumn()!=1)throw new Fault('Full installation backup requires the dedicated installation administrator.');
  $data=$c->atomic(function()use($c,$h){$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$tables=$c->query('SHOW TABLES')->fetchAll(\PDO::FETCH_COLUMN);$data=['format'=>'readyfinance-backup','version'=>1,'installation_uuid'=>$c->config['installation_uuid'],'created_at'=>Core::now(),'tables'=>[],'files'=>[]];foreach($tables as $t){if($t==='login_attempts')continue;$data['tables'][$t]=$c->all('SELECT * FROM `'.$t.'`');}foreach($c->all('SELECT storage_key,checksum FROM documents WHERE household_id=?',[$h]) as $f){$path=$c->config['storage'].'/documents/'.$f['storage_key'];if(!is_file($path)||hash_file('sha256',$path)!==$f['checksum'])throw new Fault('A document is missing or damaged. Resolve it before backup.');$data['files'][$f['storage_key']]=base64_encode(file_get_contents($path));}return $data;});
  $salt=random_bytes(16);$key=hash_pbkdf2('sha256',$password,$salt,600000,32,true);$nonce=random_bytes(12);$tag='';$cipher=openssl_encrypt(json_encode($data,JSON_THROW_ON_ERROR),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag,'RPF2');if($cipher===false)throw new Fault('Backup encryption failed.',500);$bytes='RPF2'.$salt.$nonce.$tag.$cipher;$c->audit($h,$u,'backup.created',null);header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="readyfinance-'.gmdate('Y-m-d-His').'.rpf"');header('Content-Length: '.strlen($bytes));echo $bytes;
 }
}
